// Payload de Supabase Database Webhook: { type: 'INSERT', record: {...} }
const r = $input.first().json.record ?? $input.first().json;
if (!r || !r.name) return [];
const partes = [
  `🎙 Nueva solicitud en malonicrecords`,
  `${r.name} · ${r.email}`,
  r.service ? `Servicio: ${r.service}` : null,
  r.project ? `Proyecto: ${r.project}` : null,
  r.message ? `“${String(r.message).slice(0, 180)}”` : null,
  `Revisar: https://malonic-website.vercel.app/admin`,
].filter(Boolean);
return [{ json: { mensaje: partes.join('\n') } }];
